package dev.thefoolish.generated.createanotepadappthatusesa;import android.app.*;import android.graphics.*;import android.graphics.drawable.*;import android.os.*;import android.view.*;import android.widget.*;public abstract class AppScreen extends Activity{protected LinearLayout body;protected LocalStore store;private TextView topTitle;private LinearLayout bottomNav;protected final int BG=Color.rgb(15,17,22),SURFACE=Color.rgb(27,30,38),SURFACE2=Color.rgb(36,40,50),TEXT=Color.rgb(238,240,246),MUTED=Color.rgb(164,171,187);@Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);store=new LocalStore(this);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(BG);LinearLayout bar=new LinearLayout(this);bar.setOrientation(LinearLayout.VERTICAL);bar.setPadding(dp(20),dp(12),dp(20),dp(10));TextView brand=text("Create A Notepad App That Uses A",12,false);brand.setTextColor(MUTED);bar.addView(brand);topTitle=text("Home",24,true);bar.addView(topTitle);root.addView(bar,new LinearLayout.LayoutParams(-1,-2));ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(16),dp(8),dp(16),dp(24));scroll.addView(body,new ScrollView.LayoutParams(-1,-2));root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));bottomNav=new LinearLayout(this);bottomNav.setOrientation(LinearLayout.HORIZONTAL);bottomNav.setBackgroundColor(SURFACE);root.addView(bottomNav,new LinearLayout.LayoutParams(-1,-2));setContentView(root);if(Build.VERSION.SDK_INT>=21){root.setOnApplyWindowInsetsListener((v,i)->{bar.setPadding(dp(20),i.getSystemWindowInsetTop()+dp(10),dp(20),dp(10));bottomNav.setPadding(dp(6),dp(6),dp(6),i.getSystemWindowInsetBottom()+dp(6));return i;});root.requestApplyInsets();}render();}protected abstract void render();protected void title(String s){topTitle.setText(s);}protected void subtitle(String s){TextView t=text(s,14,false);t.setTextColor(MUTED);body.addView(t,margin(-1,-2,0,0,0,12));}protected void section(String s){body.addView(text(s,18,true),margin(-1,-2,0,10,0,8));}protected TextView text(String v,int size,boolean bold){TextView t=new TextView(this);t.setText(v);t.setTextColor(TEXT);t.setTextSize(size);t.setTypeface(android.graphics.Typeface.create("sans-serif",bold?1:0));t.setGravity(Gravity.CENTER_VERTICAL);return t;}protected EditText field(String hint){EditText e=new EditText(this);e.setHint(hint);e.setSingleLine(true);e.setTextColor(TEXT);e.setHintTextColor(MUTED);e.setPadding(dp(14),0,dp(14),0);e.setBackground(round(SURFACE,14));e.setMinHeight(dp(52));e.setContentDescription(hint);return e;}protected Button button(String label){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setTextColor(TEXT);b.setMinHeight(dp(48));b.setContentDescription(label);b.setBackground(round(SURFACE2,14));b.setLayoutParams(margin(-1,dp(50),0,6,0,6));return b;}protected LinearLayout card(String h,String s){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(16),dp(14),dp(16),dp(14));c.setBackground(round(SURFACE,16));c.addView(text(h,16,true));if(s!=null&&!s.isEmpty()){TextView t=text(s,13,false);t.setTextColor(MUTED);c.addView(t);}c.setLayoutParams(margin(-1,-2,0,0,0,10));return c;}protected void nav(String[] labels,Class[] screens){bottomNav.removeAllViews();for(int x=0;x<labels.length;x++){final Class target=screens[x];TextView item=text(labels[x],11,false);item.setGravity(Gravity.CENTER);item.setMinHeight(dp(52));item.setContentDescription("Open "+labels[x]);item.setOnClickListener(v->AppNavigator.open(this,target));bottomNav.addView(item,new LinearLayout.LayoutParams(0,dp(52),1));}}protected GradientDrawable round(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}protected LinearLayout.LayoutParams margin(int w,int h,int l,int t,int r,int b){LinearLayout.LayoutParams q=new LinearLayout.LayoutParams(w,h);q.setMargins(dp(l),dp(t),dp(r),dp(b));return q;}protected int dp(int v){return(int)(v*getResources().getDisplayMetrics().density+.5f);}}